describe("doctests of sympy.sets.setexpr", () => {
  it("(a + b).set", () => {
    expect(sympyStr(new SetOp('Union', [interval(Rational.of(1n, 1n, { gcd: 1n }), Rational.of(6n, 1n, { gcd: 1n }), false, false), interval(Rational.of(10n, 1n, { gcd: 1n }), Rational.of(15n, 1n, { gcd: 1n }), false, false)]))).toBe('Union(Interval(1, 6), Interval(10, 15))');
  });
  it("(2*a + b).set", () => {
    expect(sympyStr(interval(Rational.of(1n, 1n, { gcd: 1n }), Rational.of(20n, 1n, { gcd: 1n }), false, false))).toBe('Interval(1, 20)');
  });
});

